"""Mission authoring record. Applies revisions to the frozen original catalog, not a runtime dependency."""
import json
from pathlib import Path
base=Path(__file__).resolve().parent
raw=(base/'baseline/component-records.ts').read_text().split('export const componentRecords: unknown = ',1)[1].strip().removesuffix(';')
pack=json.loads(raw);pack['version']='1.1.0'
def responsive(condition,restructure,preserved,focus):
 return dict(condition=condition,restructure=restructure,preservedInformation=preserved,focusContinuity=focus)
def check(id,requirement,method,severity,passEvidence):return dict(id=id,requirement=requirement,method=method,severity=severity,passEvidence=passEvidence)
common=[
 check('page-overflow','Failure when ordinary page content produces unintended horizontal overflow; a declared two-dimensional comparison region is evaluated separately.','browser','high','At 375, 768 and 1440 CSS px and enlarged text, measure document width and locate the offending node; repair its layout instead of globally clipping overflow.'),
 check('scroll-discovery','Review each genuinely overflowing region for a perceptible cue or reachable alternative control, plus keyboard and touch access.','keyboard','high','Record axis, task, accessible name, focus path and cue/control; test keyboard scrolling or equivalent navigation and swipe. Hidden scrollbar alone is neither pass nor failure.'),
 check('nested-scroll','Review multiple scroll owners; unnecessary same-axis nesting can strand focus, wheel or touch input.','browser','medium','Inventory page, collection, filter and dialog scroll owners; justify containment per task and exercise boundaries. Region count alone cannot determine a failure.'),
 check('focus-reflow','Failure when a layout change loses the focused record/field, enters a hidden duplicate or changes keyboard task order incoherently.','keyboard','high','Resize with a field or row action focused; preserve identity, draft/query and logical order, then complete the task in both Tab directions.')]
for spec in pack['components']+pack['compositions']:
 spec['revision']=2
 spec['checks'].extend(common)
 spec['provenance']['attribution']='Original UDI Mission 009 contracts revised by Mission 011; no external code, prose or assets reproduced.'
 spec['provenance']['reviewedAt']='2026-10-30'
 spec['evidence'].append(dict(artifact='Original UDI Mission 011 responsive and scroll revision',url=None,accessedAt='2026-10-30',relationship='original',licenseStatus='verified',licenseExpression='MIT'))
 refs=[('W3C WAI Reflow','https://www.w3.org/WAI/WCAG22/Understanding/reflow.html'),('MDN scrollbar-width reference','https://developer.mozilla.org/en-US/docs/Web/CSS/Reference/Properties/scrollbar-width')]
 for name,url in refs:
  if not any(r['url']==url for r in spec['provenance']['references']):
   spec['provenance']['references'].append(dict(name=name,url=url))
   spec['evidence'].append(dict(artifact=name,url=url,accessedAt='2026-10-30',relationship='supports',licenseStatus='reference-only',licenseExpression=None))
table,filters,form=pack['components'];workspace=pack['compositions'][0]
table['responsive']=[
 responsive('Column comparison is the primary task and readable columns exceed available width, including tablet or enlarged text.','Keep a semantic table in one named horizontal scroll region with native scrollbar visibility (auto); preserve row identity and place the frequent authorized action beside the identity or in a persistent, non-overlapping action area without horizontal travel. Do not convert comparison tasks to cards automatically.',['Record identity and full name access','Critical status, permission and units','Every comparable column and selected scope','Prioritized authorized action without horizontal travel'],'Retain record IDs, query and sort; reveal focused cells/controls without obscuring them. Restore the same record action after details.'),
 responsive('Individual record lookup or editing matters more than simultaneous column comparison on a narrow screen.','Use a task-focused row summary with identity, critical status/value and authorized primary action; disclose labeled secondary fields on demand. A summary is not a forced card layout. Keep one active semantic representation and offer comparison when the task still requires it.',['Stable identity','Critical values and units','Explicit read-only permission reason','All secondary values through a named details control'],'Details return to the same record; do not duplicate tabbable controls or lose selection on layout changes.'),
 responsive('No records are displayed: initial empty, zero matches, loading or error.','Keep query, scope and recovery meaningful; do not create an empty horizontal scroll track from a minimum-width header. Hide or constrain the unused table region while preserving loading/status announcements and Clear or Retry.',['Query and result meaning','Recovery actions and permission context'],'Keep focus on the initiating query/control, or move deliberately to an announced recovery destination.')]
table['checks'].extend([
 check('priority-action','Failure when a declared essential row action cannot be reached without horizontal travel in a narrow viewport.','browser','high','At 375 CSS px and scrollLeft zero, locate and operate the frequent permitted action; verify a denied record exposes a reason and no unauthorized action. Repeat at 768 and 1440.'),
 check('truncation-access','Failure when critical identity/value is clipped without an operable full-content route.','browser','high','Use long names, text enlargement and missing values; demonstrate wrap or keyboard/touch-accessible detail. Title-only hover text does not suffice.'),
 check('comparison-or-summary','Review the responsive strategy against the actual task; hidden priority columns and automatic card conversion can impair comparison.','expert','high','Declare which values/actions are essential; complete both single-record work and cross-record comparison, recording any extra disclosure cost.')])
table['visual']['discoverability']='Anchor the frequent permitted action near record identity, reachable at horizontal origin on narrow screens; secondary values/actions may use named details/overflow with a permission reason. Native scrollbar auto is the comparison default; additional controls and cues must be verified before considering local concealment.'
filters['responsive']=[
 responsive('Facets crowd search/results at narrow or tablet widths, or selected values are long.','Move advanced facets into a named disclosure or one focus-managed sheet. Keep query, result meaning, active conditions and Clear reachable; prefer wrapping chips. Horizontal chip scrolling is conditional: show an edge cue or previous/next controls, reveal focused removals and never silently clip selected scope.',['Active query and applied conditions','Unapplied draft meaning when applicable','Result count and reset scope'],'Closing returns to the trigger; removing a chip moves focus to the next relevant chip or Clear/search. Result updates do not steal typing focus.'),
 responsive('A filter sheet is shorter than its fields, especially with an on-screen keyboard.','Use one vertical body scroll owner, with Apply/reset reachable by scrolling or non-obscuring actions. Avoid an independently scrolling chip rail nested inside the sheet when wrapping suffices. Scrollbar auto is default; conceal only with equivalent discoverable operation.',['Draft values and active query distinction','All filter options and labels','Apply/clear actions'],'Bring focused options into the usable viewport and return to the same trigger; preserve drafts on resize according to the declared policy.')]
form['responsive']=[
 responsive('Fields or actions no longer fit readable columns, including narrow, tablet, enlarged text or short usable viewport.','Stack related fields in reading order. For an overlay, give its body one vertical scroll owner constrained by the usable viewport; keep Save/Cancel reachable without clipping and reveal focused inputs/errors above any sticky actions. Use native scrollbar auto by default, not global overflow locking.',['Identity, labels and entered values','Validation/server errors and unsaved status','Save scope, permissions and revision'],'Retain the same field across resize. Error links reveal the containing section and scroll the target clear of fixed chrome; close returns to the invoker.'),
 responsive('The page or another overlay already owns scrolling.','Choose page editing or one modal focus owner deliberately; avoid simultaneously scrolling form, dialog and page for the same task. A temporary modal background lock must be scoped, preserve page position and restore scrolling on every exit.',['Dirty data and recoverable outcome','Reachable submit, cancel and close'],'Test Tab and Shift+Tab, Escape and error focus in a short viewport; do not treat a transient BODY stop alone as proof of background control access.')]
form['checks'].append(check('short-dialog','Failure when Save/Cancel or a focused correction cannot be brought into the usable dialog viewport.','browser','critical','At 375 by 500 CSS px, then simulated reduced visual viewport, reach inputs/errors and Save/Cancel by keyboard and scroll; check occlusion by footer, preserve draft on resize and restore page position on exit.'))
workspace['responsive']=[
 responsive('Collection, filters and editor compete for readable width or height.','Choose comparison-scroll versus single-record summary from the task. Keep identity, critical status/permission and frequent permitted action available at narrow widths; move details to a route or one modal surface. Do not nest independent vertical panes unless their task requires them.',['Active scope, query, sort and page','Selection and permitted row actions','Dirty form and return-record identity'],'Exactly one overlay owns interaction. Preserve focus and draft when switching layout; restore the invoker or a meaningful collection fallback.'),
 responsive('Workspace contains page, table, navigation or chips that overflow.','Assign one owner per axis/task: page owns ordinary vertical reading; comparison table owns necessary horizontal movement; navigation/chips wrap or provide reachable controls and reveal selection. Native scrollbar auto is default. Conceal locally only after equivalent discovery and keyboard/touch operation are demonstrated; repair accidental page overflow instead of clipping it.',['Navigation/active filter meaning','All comparison values','Recovery and editor actions'],'Match DOM task order to visible order; focused navigation, chips and records scroll into view without shifting unrelated regions.')]
workspace['layoutModes'][1]['restructuring']='Prioritize query/scope, then record identity/status and frequent action at horizontal origin. Choose table scrolling for comparison or summary/details for individual work; move editor to one focus-managed surface or route, preserve query/draft and avoid redundant scrollbars in empty states.'
workspace['checks'].append(check('task-action-access','Failure when the declared essential action or state-recovery control is clipped or requires traversing unrelated horizontal columns.','browser','high','Complete the declared primary task at 375/768/1440 and 375 by 500; verify permissions, no accidental page overflow, stable focus and accessible filters in populated/empty/error/edit states.'))
Path('packages/knowledge/src/component-records.ts').write_text('// Original UDI Mission 009 contracts, revised by Mission 011. MIT; citation-only external references.\nexport const componentRecords: unknown = '+json.dumps(pack,indent=2,ensure_ascii=False)+';\n')
